    """For each column with coordinates, fill gaps vertically"""
    result = [[input_grid[r][c] for c in range(len(input_grid[0]))] for r in range(len(input_grid))]

    # Group by column
    by_col = defaultdict(list)
    for r,c in coords:
        by_col[c].append(r)

    for c in by_col:
        rows = sorted(by_col[c])
        if len(rows) < 2:
            continue  # single cell, no gaps to fill
        # Fill between min and max row
        for r in range(rows[0], rows[-1]+1):
            if input_grid[r][c] == 4:
                result[r][c] = new_val

    return result

